def check(args, got):
    merged = []
    for s, e in sorted([c - r, c + r] for c, r in args[0]):
        if merged and s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    expected, prev = [], None
    for s, e in merged:
        expected.append([prev, s])
        prev = e
    expected.append([prev, None])
    inf = float("inf")
    if not isinstance(got, list) or len(got) != len(expected):
        return False
    for pair, (lo, hi) in zip(got, expected):
        if not isinstance(pair, list) or len(pair) != 2:
            return False
        a, b = pair
        if isinstance(a, bool) or isinstance(b, bool):
            return False
        a = None if (a is None or a == -inf) else a
        b = None if (b is None or b == inf) else b
        if (a is None) != (lo is None) or (b is None) != (hi is None):
            return False
        if (lo is not None and a != lo) or (hi is not None and b != hi):
            return False
    return True
